#pragma once
#include <vector>

namespace shop {

struct Item {
  long price;
  int qty;
};

class Cart {
 public:
  explicit Cart(std::vector<Item> items);
  long total() const;
  int count() const;

 private:
  std::vector<Item> items_;
};

std::string format_price(long cents);

}  // namespace shop

files.src/cart.cpp:
#include "shop/cart.hpp"

#include <string>

namespace shop {

Cart::Cart(std::vector<Item> items) : items_(std::move(items)) {}

long Cart::total() const {
  long sum = 0;
  for (const Item &i : items_) sum += i.price * i.qty;
  return sum;
}

int Cart::count() const { return static_cast<int>(items_.size()); }

std::string format_price(long cents) { return "$" + std::to_string(cents / 100); }

}  // namespace shop

